BEGIN;
CREATE TABLE IF NOT EXISTS retail_deals(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,vin CHAR(17) NOT NULL,lead_source TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('lead_created','vehicle_reserved','desking','credit_consented','lender_submitted','documents_ready','signed','delivered','follow_up','cancelled')),record JSONB NOT NULL,idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS retail_deal_events(id BIGSERIAL PRIMARY KEY,deal_id BIGINT NOT NULL REFERENCES retail_deals(id),tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_state TEXT,to_state TEXT,idempotency_key TEXT,evidence_digest TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(deal_id,idempotency_key));
CREATE TABLE IF NOT EXISTS retail_sync_jobs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('dms','crm','oem','lender','valuation','esign','payment','messaging')),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','quarantined')),payload JSONB NOT NULL,requested_by TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_retail_deals_tenant_state ON retail_deals(tenant_id,state,vin);
COMMIT;
